		cDate.value = inv.date;
		cDate.numFmt = "@";
		cDate.font = {
			name: fontName,
			size: 11,
			color: { argb: "FF334155" }
		};
		cDate.alignment = {
			horizontal: horizontalAlign,
			vertical: "middle"
		};
		registerWidth(2, inv.date);
		const cSupName = row.getCell(3);
